import { useRegistration } from '~/entities/biometric/lib/use-registration';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar } from '~/shared/lib/toast';

export const BiometricRegister = () => {
  const { register } = useRegistration();
  const { openAlertDialog } = useAlertDialog();

  const handleRegisterClick = () => {
    openAlertDialog({
      title: '생체인증 등록',
      message: '생체인증을 등록하시겠습니까?',
      buttonLabel: ['취소', '확인'],
      onConfirmClick: () => {
        register({
          success: () => {
            notiBar('생체인증 등록이 완료되었습니다.');
          },
          error: (error: string) => {
            openAlertDialog({
              title: '생체인증 등록 오류',
              message: error,
            });
          },
        });
      },
      onCancelClick: () => {
        // 취소 시 아무 작업 없음
      },
    });
  };

  return (
    <button type="button" className="menu-btn" onClick={handleRegisterClick}>
      <span className="menu-btn-text">{i18n.t('resetBiometric')}</span>
    </button>
  );
};
